void mainImage( out vec4 fragColor, in vec2 fragCoord)
{   

    vec2 uv3 = fragCoord/iResolution.xy; 

    vec2 uvv = fragCoord.xy;
    vec2 center =  vec2(390.,125.);
    vec2 center2 = vec2(320.,190.);
    vec2 orta = vec2(400.,225.);
    vec2 center4 = vec2(350.,280.);
    vec2 center5 = vec2(450.,280);
    vec2 center6 = vec2(470.,180.);
    vec2 center7 = vec2(400.,250.);
    vec2 center8 = vec2(420.,250.);
    vec2 center9 = vec2(420.,220.);

    float radius = 0.13 * iResolution.y;
    float radius2 = 0.1 * iResolution.y;
    float radius3 = 0.01 * iResolution.y;
    float radius4 = 0.02 * iResolution.y;


    vec3 white = vec3(242./255.,242./255.,242./255.);
    vec3 orange = vec3(255.0/255.0,215.0/255.,0.);
    vec3 black = vec3(0.0,0.0,.0);
    vec3 red = vec3(1.0,0.0,.0);
    fragColor = vec4 (1.0,1.0,1.0,1.0);
    fragColor = vec4(215.0/255.0,235.0/255.0,242./255.,0.0);
    float d = length (center - uvv);
    float d2 = length (center2 - uvv);
    float d3 = length (orta - uvv);
    float d4 = length (center4 - uvv);
    float d5 = length (center5 - uvv);
    float d6 = length (center6 - uvv);
    float d7 = length (center7 - uvv);
    float d8 = length (center8 - uvv);
    float d9 = length (center9 - uvv);



    if (d8 <= radius3){
        fragColor = vec4 (black,1.0);
    }
    else if (d9 <= radius4 && fragCoord.y <= center9.y){
        fragColor = vec4 (red,1.0);
    }
    else if (d7 <= radius3){
        fragColor = vec4 (black,1.0);
    }
    else if (d2 <=radius)
        fragColor = vec4(white,1.0);
    else if (d <= radius){
        fragColor = vec4 (white,1.0);
    }
    else if (d3 <= radius2){
        fragColor = vec4 (orange,1.0);
    }
    else if (d4 <= radius){
        fragColor = vec4 (white,1.0);
    }
    else if (d5 <= radius){
        fragColor = vec4 (white,1.0);
    }
    else if (d6 <= radius){
        fragColor = vec4 (white,1.0);
    }

}
